                                                                                                                                                                                                     
  CREATE TABLE "CHECK_FORM"                                                                                                                                                               
   (	"FORM_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 2 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,     
	"CREATED_BY" NUMBER(20,0),                                                                                                                                                                          
	"CREATION_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                               
	"UPDATED_BY" NUMBER(20,0),                                                                                                                                                                          
	"UPDATED_DATE" DATE DEFAULT sysdate NOT NULL ENABLE,                                                                                                                                                
	"REMARK" NVARCHAR2(512),                                                                                                                                                                            
	"TENANT_ID" NUMBER(20,0) DEFAULT 3 NOT NULL ENABLE,                                                                                                                                                 
	"FORM_SERIAL_NO" NVARCHAR2(256),                                                                                                                                                                    
	"NAME" NVARCHAR2(256),                                                                                                                                                                              
	"CLASSIFY_ID" NUMBER(20,0),                                                                                                                                                                         
	"PLAN_ID" NUMBER(20,0),                                                                                                                                                                             
	"SORT_NUM" NUMBER(20,0) DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                  
	"DEL_FLAG" NUMBER(1,0) DEFAULT 0 NOT NULL ENABLE,                                                                                                                                                   
	"IS_ENABLE" NUMBER(1,0) DEFAULT 1 NOT NULL ENABLE,                                                                                                                                                  
	"BASE_DEPT_ID" NVARCHAR2(36),                                                                                                                                                                       
	 PRIMARY KEY ("FORM_ID")                                                                                                                                                                            
  USING INDEX  ENABLE                                                                                                                                                                                
   ) ;                                                                                                                                                                                               

